def todict(self):
    """Convert to a dictionary of data.
    """
    data = {}
    for key in self.data:
        data[key] = self.data[key]
    return data


def fromfile(self, file_path, start_addr=0):
    """Load data from a file.

    The file is assumed to be a binary file of data.
    The first byte of the file will be interpreted as the starting address.
    """
    with open(file_path, 'rb') as f:
        data = f.read()
        self.frombytes(data, start_addr)


def tofile(self, file_path):
    """Save data to a file.

    The file is assumed to be a binary file of data.
    """
    with open(file_path, 'wb') as f:
        f.write(self.tobytes())


def frombytes(self, bytes, start_addr=0):
    """Load data from bytes.

    The bytes are assumed to be in the order of memory, starting at
    ``start_addr``.
    """
    if isinstance(bytes, bytes):
        self.start_addr = start_addr
        for i in range(0, len(bytes)):
            self.data[start_addr + i] = bytes[i]
    else:
        raise ValueError("Data must be a bytes.")


def tobytes(self):
    """Convert to bytes.
    """
    bytes = []
    for key in self.data:
        bytes.append(self.data[key])
    return bytes


